package io.github.jesterportfolio.hearth.auraproof;
import java.util.*;import io.github.jesterportfolio.hearth.auraproof.PolicyProof.Stack;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static io.github.jesterportfolio.hearth.auraproof.PolicyProof.*;
class PolicyProofTest{
 private long count(List<Stack> s){return s.stream().mapToLong(Stack::amount).sum();}
 @Test void world_table_preserves_undecided_public_policy(){assertFalse(pvp(Role.PUBLIC_HOME,true));assertFalse(pvp(Role.NOVICE_RESOURCE,true));assertFalse(pvp(Role.PRIVATE_HOME,false));assertTrue(pvp(Role.PRIVATE_HOME,true));assertTrue(pvp(Role.RESOURCE,false));assertEquals(.05,dropRate(Role.NETHER));assertEquals(.30,dropRate(Role.END));assertThrows(IllegalStateException.class,()->dropRate(Role.PUBLIC_HOME));}
 @Test void zero_and_full_drop_rates_conserve_every_item(){var source=List.of(new Stack("diamond",64),new Stack("sword-meta-a",1));for(var unit:DropUnit.values()){var none=split(source,0,unit,false,new Random(1));assertEquals(source,none.kept());assertTrue(none.dropped().isEmpty());var all=split(source,1,unit,false,new Random(1));assertTrue(all.kept().isEmpty());assertEquals(source,all.dropped());}}
 @Test void per_item_and_per_stack_never_duplicate_or_lose_quantities(){for(var unit:DropUnit.values())for(int seed=0;seed<500;seed++){var split=split(List.of(new Stack("diamond-meta",64),new Stack("bow-enchanted",1)),.30,unit,false,new Random(seed));assertEquals(65,count(split.kept())+count(split.dropped()));assertTrue(split.kept().stream().allMatch(s->s.identity().equals("diamond-meta")||s.identity().equals("bow-enchanted")));}}
 @Test void charm_is_consumed_once_and_other_penalties_are_bypassed(){var split=split(List.of(new Stack("charm",2),new Stack("ore",64)),1,DropUnit.ITEM,true,new Random(3));assertEquals(1,split.consumedCharms());assertEquals(65,count(split.kept()));assertTrue(split.dropped().isEmpty());assertThrows(IllegalArgumentException.class,()->split(List.of(new Stack("ore",2)),.3,DropUnit.ITEM,true,new Random(1)));}
 @Test void average_uses_a_fixed_denominator_including_custom_skills(){var levels=Map.of("a/mining",20,"hearth/metallurgy",10);assertTrue(new LevelRule(Scope.AVERAGE,List.of("a/mining","hearth/metallurgy"),15).allows(true,levels));assertFalse(new LevelRule(Scope.AVERAGE,List.of("a/mining","hearth/metallurgy"),16).allows(true,levels));assertFalse(new LevelRule(Scope.AVERAGE,List.of("a/mining","missing"),1).allows(true,levels));}
 @Test void specific_sum_and_multiple_conditions_are_independent(){var levels=Map.of("a/mining",20,"hearth/metallurgy",10);assertTrue(new LevelRule(Scope.SPECIFIC,List.of("a/mining"),20).allows(true,levels));assertTrue(new LevelRule(Scope.SUM,List.of("a/mining","hearth/metallurgy"),30).allows(true,levels));assertFalse(new LevelRule(Scope.ALL,List.of("a/mining","hearth/metallurgy"),15).allows(true,levels));}
 @Test void unloaded_data_never_grants_entry_even_with_zero_requirement(){assertFalse(new LevelRule(Scope.SPECIFIC,List.of("mining"),0).allows(false,Map.of("mining",1)));}
 @Test void loot_and_xp_decisions_are_sampled_once_per_action(){var once=new RewardOnce();var id=UUID.randomUUID();var first=once.begin(id,true,new Random(1));assertSame(first,once.begin(id,true,new Random(7)));assertEquals(.5,first.skillFactor());once.finish(id);assertNotSame(first,once.begin(id,true,new Random(1)));}
 @Test void non_penalized_reward_is_unchanged(){assertEquals(new RewardDecision(false,false,1),new RewardOnce().begin(UUID.randomUUID(),false,new Random(1)));}
 @Test void combat_tags_both_users_and_refreshes_without_shortening(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();var combat=new Combat(30);combat.hit(a,b,100);assertTrue(combat.blocked(a,129));assertTrue(combat.blocked(b,129));assertFalse(combat.blocked(a,130));combat.hit(a,b,120);combat.hit(a,b,110);assertEquals(150,combat.deadline(a));}
 @Test void reconnect_can_restore_the_remaining_combat_deadline(){var id=UUID.randomUUID();var combat=new Combat(30);combat.restore(id,100);combat.restore(id,90);assertTrue(combat.blocked(id,99));assertFalse(combat.blocked(id,100));}
 @Test void final_admission_rechecks_all_paths_and_generation(){var ok=new Admission(true,true,true,false,3);assertTrue(ok.commit(ok));for(var denied:List.of(new Admission(false,true,true,false,3),new Admission(true,false,true,false,3),new Admission(true,true,false,false,3),new Admission(true,true,true,true,3),new Admission(true,true,true,false,4)))assertFalse(ok.commit(denied));}
 @Test void tpa_requires_actual_recipient_acceptance_and_single_move(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();var ok=new Admission(true,true,true,false,1);var tpa=new Tpa(a,b,100);assertFalse(tpa.accept(a,0,ok,ok));assertFalse(tpa.move(1,ok,ok,ok));assertTrue(tpa.accept(b,1,ok,ok));assertTrue(tpa.move(2,ok,ok,ok));assertFalse(tpa.move(2,ok,ok,ok));}
 @Test void combat_started_after_acceptance_prevents_tpa_commit(){var ok=new Admission(true,true,true,false,1);var combat=new Admission(true,true,true,true,1);var a=UUID.randomUUID();var b=UUID.randomUUID();var tpa=new Tpa(a,b,100);assertTrue(tpa.accept(b,0,ok,ok));assertFalse(tpa.move(1,ok,combat,ok));assertFalse(tpa.move(1,ok,ok,combat));}
 @Test void expired_requests_and_changed_housing_generation_are_denied(){var ok=new Admission(true,true,true,false,1);var newer=new Admission(true,true,true,false,2);var requester=UUID.randomUUID();var recipient=UUID.randomUUID();var expired=new Tpa(requester,recipient,10);assertTrue(expired.accept(recipient,0,ok,ok));assertFalse(expired.move(10,ok,ok,ok));var changed=new Tpa(requester,recipient,100);assertTrue(changed.accept(recipient,0,ok,ok));assertFalse(changed.move(1,ok,newer,ok));}
 @Test void vanilla_xp_third_is_separate_from_skill_xp(){assertEquals(67,loseThird(100));assertEquals(50,100*.5);assertThrows(IllegalArgumentException.class,()->loseThird(-1));}
}
